15	fn main() {
16	    println!("cargo:rerun-if-changed=build.rs");
17	    println!("cargo:rerun-if-env-changed=LOG");
18	    println!("cargo:rerun-if-env-changed=TG_USER_DIR");
19	    println!("cargo:rerun-if-env-changed=TG_USER_VERSION");
20	    println!("cargo:rerun-if-env-changed=TG_USER_CRATE");
21	    println!("cargo:rerun-if-env-changed=TG_USER_LOCAL_DIR");
22	    println!("cargo:rerun-if-env-changed=TG_SKIP_USER_APPS");
23	    println!("cargo:rerun-if-env-changed=CARGO_FEATURE_EXERCISE");
