45	fn write_linker() {
46	    let ld = PathBuf::from(env::var_os("OUT_DIR").unwrap()).join("linker.ld");
47	    fs::write(&ld, tg_linker::NOBIOS_SCRIPT).unwrap_or_else(|err| {
48	        panic!("failed to write linker script to {}: {}", ld.display(), err)
