53	fn is_packaged_build() -> bool {
54	    let out_dir = PathBuf::from(env::var_os("OUT_DIR").unwrap());
55	    let out_dir = out_dir.to_string_lossy();
56	
57	    let manifest_dir = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").unwrap());
58	    let manifest_dir = manifest_dir.to_string_lossy();
59	
60	    out_dir.contains("/target/package/")
61	        || out_dir.contains("\\target\\package\\")
62	        || manifest_dir.contains("/target/package/")
63	        || manifest_dir.contains("\\target\\package\\")
64	}
