198	fn ensure_tg_user() -> PathBuf {
199	    // 优先使用 TG_USER_DIR 显式指定的目录
200	    if let Ok(dir) = env::var("TG_USER_DIR") {
201	        let path = PathBuf::from(dir);
202	        if path.join("Cargo.toml").exists() {
203	            return path;
204	        }
205	    }
206	
207	    // 从 .cargo/config.toml [env] 读取三个配置项
208	    let crate_name = env::var("TG_USER_CRATE")
209	        .expect("TG_USER_CRATE not set; add it to .cargo/config.toml [env]");
210	    let local_dir_name = env::var("TG_USER_LOCAL_DIR")
211	        .expect("TG_USER_LOCAL_DIR not set; add it to .cargo/config.toml [env]");
212	    let version = env::var("TG_USER_VERSION")
213	        .expect("TG_USER_VERSION not set; add it to .cargo/config.toml [env]");
214	
215	    let manifest_dir = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").unwrap());
216	    let tg_user_dir = manifest_dir.join(&local_dir_name);
217	
218	    // 本地缓存目录已存在则直接使用
219	    if tg_user_dir.join("Cargo.toml").exists() {
220	        ensure_workspace_table(&tg_user_dir);
221	        return tg_user_dir;
222	    }
223	
224	    // 从 crates.io 克隆指定包
225	    let crate_spec = format!("{crate_name}@{version}");
226	    let status = Command::new("cargo")
227	        .args([
228	            "clone",
229	            crate_spec.as_str(),
230	            "--",
231	            tg_user_dir.to_string_lossy().as_ref(),
232	        ])
233	        .status()
234	        .unwrap_or_else(|e| panic!("failed to execute cargo clone {crate_spec}: {e}"));
235	
236	    if !status.success() {
237	        panic!(
238	            "failed to clone {crate_spec} into {}; ensure cargo-clone is installed or set TG_USER_DIR",
239	            tg_user_dir.display()
240	        );
241	    }
242	
243	    if !tg_user_dir.join("Cargo.toml").exists() {
244	        panic!(
245	            "{crate_spec} clone did not produce a valid crate at {}",
246	            tg_user_dir.display()
247	        );
248	    }
249	
250	    // 克隆后补加 [workspace]，防止父 workspace 将其识别为非成员而报错
251	    ensure_workspace_table(&tg_user_dir);
252	
253	    tg_user_dir
254	}
255	
256	/// 若 Cargo.toml 末尾尚无 [workspace] 表，则追加一个空的，
257	/// 使该 crate 成为独立 workspace 根，避免父 workspace 冲突。
258	fn ensure_workspace_table(dir: &PathBuf) {
259	    let cargo_toml = dir.join("Cargo.toml");
260	    let content = fs::read_to_string(&cargo_toml).unwrap_or_default();
261	    if !content.contains("[workspace]") {
262	        fs::write(&cargo_toml, format!("{}
263	[workspace]
264	", content))
265	            .unwrap_or_else(|err| panic!("failed to patch Cargo.toml in {}: {}", dir.display(), err));
266	    }
267	}

